      "qualname": "funcy/calc.py::cache",
      "source": "def cache(timeout, key_func=None):
    """Caches a function results for timeout seconds."""
    timeout = timedelta(seconds=timeout) if isinstance(timeout, int) else timeout
    if key_func is None:
        key_func = lambda *a, **kw: a + tuple(sorted(kw.items())) if kw else a

    def decorator(f):
        c = {}
        @wraps(f)
        def w(*args, **kwargs):
            k = key_func(*args, **kwargs)
            e = c.get(k)
            if e:
                if datetime.now() - e[1] < timeout:
                    return e[0]
                del c[k]
            r = f(*args, **kwargs)
            c[k] = (r, datetime.now())
            return r
        w.memory = c
        w.skip = SkipMemoization
        def inv(*args, **kwargs):
            c.pop(key_func(*args, **kwargs), None)
        w.invalidate = inv
        def inv_all():
            c.clear()
        w.invalidate_all = inv_all
        return w
    return decorator"
